  demo_images constant jsonb := '[{"id":"9b4988f5-3a9c-dd7f-1e87-cb97164ef0c9","product_id":"b932484c-98fb-f6a4-4bf3-b4131a97fd10","storage_path":"vanta-demo-v1/remera-essential/front.png","alt":"Remera Essential; imagen ilustrativa original generada con IA para demostración","position":0},{"id":"4f35d48d-1b96-f0d8-14e2-dfe7cc5c0491","product_id":"a407d197-84d3-02f7-d5bb-10cea8e7483a","storage_path":"vanta-demo-v1/remera-box/front.png","alt":"Remera Box; imagen ilustrativa original generada con IA para demostración","position":0},{"id":"33479b90-2bac-d6b4-66d7-d18f4bc632f5","product_id":"287d20bb-02b0-7abf-1ed1-5faeb2bde79d","storage_path":"vanta-demo-v1/buzo-core/front.png","alt":"Buzo Core; imagen ilustrativa original generada con IA para demostración","position":0},{"id":"95362df5-2c4e-56a8-7558-827d610597cc","product_id":"592bb001-2877-5fba-c58f-8f9dd7befd29","storage_path":"vanta-demo-v1/buzo-relax/front.png","alt":"Buzo Relax; imagen ilustrativa original generada con IA para demostración","position":0},{"id":"86d41b5e-adff-c98f-bafe-b5aa20ebdfc9","product_id":"5361ea09-80a3-470e-93c6-8de3e87c4ee8","storage_path":"vanta-demo-v1/pantalon-forma/front.png","alt":"Pantalón Forma; imagen ilustrativa original generada con IA para demostración","position":0},{"id":"7adfa83a-0478-32aa-2f37-4f710ba0fb28","product_id":"3d805548-7c4b-949b-8922-3e59ca73b1c1","storage_path":"vanta-demo-v1/pantalon-cargo/front.png","alt":"Pantalón Cargo; imagen ilustrativa original generada con IA para demostración","position":0},{"id":"e76acf04-c9ad-091a-1bc7-96c611e75633","product_id":"be4c0686-4506-4b1c-c4e5-a8bdb8105c87","storage_path":"vanta-demo-v1/conjunto-studio/front.png","alt":"Conjunto Studio; imagen ilustrativa original generada con IA para demostración","position":0},{"id":"8a41d347-529d-b19d-1bd4-a0b1f7039e29","product_id":"d07af362-15e2-07a1-92db-590b75aa612b","storage_path":"vanta-demo-v1/conjunto-weekend/front.png","alt":"Conjunto Weekend; imagen ilustrativa original generada con IA para demostración","position":0}]'::jsonb;
begin
  if confirmed_project_ref <> 'evlbfjvvljbkntlozokt' then
    raise exception 'Falta confirmar el proyecto VANTA: generar el archivo con --confirm-project=evlbfjvvljbkntlozokt --output=work/vanta-demo-load.sql';
  end if;
  -- This acknowledgement is NOT proof of database identity; verify Dashboard first.
  if not exists(select 1 from storage.buckets where id='product-images' and not public
    and file_size_limit=5242880 and 'image/png'=any(allowed_mime_types)) then
    raise exception 'Bucket privado incompatible; no se modifica su configuración';
  end if;
  lock table public.categories, public.products, public.product_variants,
    public.product_images, public.inventory in share row exclusive mode;
  if exists(select 1 from jsonb_to_recordset(demo_images) as d(id uuid,product_id uuid,storage_path text,alt text,position integer) where not exists(
    select 1 from storage.objects o where o.bucket_id='product-images' and o.name=d.storage_path)) then
    raise exception 'Faltan fotografías en Storage: se esperan rutas vanta-demo-v1/<modelo>/front.png';
  end if;

  insert into public.categories(id,name,slug,active)
  select id,name,slug,true from jsonb_to_recordset(demo_categories) as d(id uuid,name text,slug text) on conflict do nothing;
  if (select count(*) from jsonb_to_recordset(demo_categories) as d(id uuid,name text,slug text) join public.categories c
    on c.slug=d.slug and c.name=d.name and c.active) <> 4 then
    raise exception 'Colisión o categoría inactiva: no se sobrescriben categorías existentes';
  end if;

  insert into public.products(id,category_id,name,slug,description,price_cents,currency,active)
  select d.id,c.id,d.name,d.slug,d.description,d.price_cents,'ARS',true
  from jsonb_to_recordset(demo_products) as d(id uuid,category_slug text,name text,slug text,description text,price_cents bigint) join public.categories c on c.slug=d.category_slug
  on conflict do nothing;
  if (select count(*) from jsonb_to_recordset(demo_products) as d(id uuid,category_slug text,name text,slug text,description text,price_cents bigint) join public.categories c on c.slug=d.category_slug
    join public.products p on p.id=d.id and p.slug=d.slug and p.category_id=c.id
      and p.name=d.name and p.description=d.description and p.price_cents=d.price_cents and p.currency='ARS' and p.active) <> 8 then
    raise exception 'Colisión o producto demo alterado: transacción cancelada sin sobrescribir';
  end if;

  insert into public.product_variants(id,product_id,sku,size,color,active)
  select id,product_id,sku,size,color,true from jsonb_to_recordset(demo_variants) as d(id uuid,product_id uuid,sku text,size text,color text) on conflict do nothing;
  if (select count(*) from jsonb_to_recordset(demo_variants) as d(id uuid,product_id uuid,sku text,size text,color text) join public.product_variants v
    on v.id=d.id and v.product_id=d.product_id and v.sku=d.sku and v.size=d.size and v.color=d.color and v.active) <> 64 then
    raise exception 'Colisión o variante demo alterada: transacción cancelada';
  end if;

  insert into public.product_images(id,product_id,storage_path,alt,position)
  select id,product_id,storage_path,alt,position from jsonb_to_recordset(demo_images) as d(id uuid,product_id uuid,storage_path text,alt text,position integer) on conflict do nothing;
  if (select count(*) from jsonb_to_recordset(demo_images) as d(id uuid,product_id uuid,storage_path text,alt text,position integer) join public.product_images i
    on i.id=d.id and i.product_id=d.product_id and i.storage_path=d.storage_path and i.alt=d.alt and i.position=d.position) <> 8 then
    raise exception 'Colisión o imagen demo alterada: transacción cancelada';
  end if;

  -- Never restock existing rows or reset reservations on repetition.
  insert into public.inventory(variant_id,on_hand,reserved)
  select id,6,0 from jsonb_to_recordset(demo_variants) as d(id uuid,product_id uuid,sku text,size text,color text) on conflict (variant_id) do nothing;
end
$vanta_demo$;

-- Independent read-only summary: no temporary or session state.
with demo_products(id) as (select unnest(array['b932484c-98fb-f6a4-4bf3-b4131a97fd10'::uuid,'a407d197-84d3-02f7-d5bb-10cea8e7483a'::uuid,'287d20bb-02b0-7abf-1ed1-5faeb2bde79d'::uuid,'592bb001-2877-5fba-c58f-8f9dd7befd29'::uuid,'5361ea09-80a3-470e-93c6-8de3e87c4ee8'::uuid,'3d805548-7c4b-949b-8922-3e59ca73b1c1'::uuid,'be4c0686-4506-4b1c-c4e5-a8bdb8105c87'::uuid,'d07af362-15e2-07a1-92db-590b75aa612b'::uuid]))
select
  (select count(*) from public.products p join demo_products d on p.id=d.id) as demo_products,
  (select count(*) from public.product_variants v join demo_products d on v.product_id=d.id) as demo_variants,
  (select count(*) from public.product_images i join demo_products d on i.product_id=d.id) as demo_images,
  (select count(*) from public.inventory i join public.product_variants v on v.id=i.variant_id
    join demo_products d on v.product_id=d.id) as demo_inventory_rows;
